import random
import string
from typing import List

# Generator for valid and interesting PCRE2 pattern strings.
# Focus: produce syntactically valid patterns that exercise diverse features:
# - Literals, character classes, escapes, Unicode, POSIX classes, properties
# - Groups: capturing, non-capturing, named, atomic, lookaround, conditionals
# - Quantifiers, alternation, anchors, backreferences, recursion, callouts, options
# - Inline modifiers and comments, verb controls, subroutines
# - Boundaries, word boundaries with locales
#
# The output must be bytes (not NUL-terminated) and <= 4096 bytes.

ASCII = string.ascii_letters
DIG = string.digits
HEX = DIG + "abcdefABCDEF"
WS = " \t\r\n\f\v"

# Some safe classes and tokens
SAFE_ESCAPES = [
    r"\d", r"\D", r"\w", r"\W", r"\s", r"\S",
    r"\h", r"\H", r"\v", r"\V", r"\R", r"\N",
    r"\t", r"\n", r"\r", r"\f", r"\a", r"\e",
]

# Unicode property names commonly supported by PCRE2
UNICODE_PROPS = [
    "L", "Lu", "Ll", "Lt", "Lm", "Lo",
    "M", "Mn", "Mc", "Me",
    "N", "Nd", "Nl", "No",
    "P", "Pc", "Pd", "Ps", "Pe", "Pi", "Pf", "Po",
    "S", "Sm", "Sc", "Sk", "So",
    "Z", "Zs", "Zl", "Zp",
    "C", "Cc", "Cf", "Cs", "Co", "Cn",
    "Greek", "Han", "Latin", "Cyrillic",
]

POSIX_CLASSES = [
    "alnum", "alpha", "ascii", "blank", "cntrl", "digit", "graph",
    "lower", "print", "punct", "space", "upper", "word", "xdigit",
]

VERBS = [
    "ACCEPT", "FAIL", "SKIP", "THEN", "PRUNE", "COMMIT",
]

INLINE_OPT_SETS = [
    "i", "m", "s", "x", "U", "J", "u",
]

QUANTIFIERS = ["?", "*", "+", "{1,3}", "{0,2}", "{2}", "{2,}?", "+?", "*?", "??"]

def rnd(r: random.Random, seq: List[str]):
    return r.choice(seq)

def maybe(r: random.Random, p=0.5):
    return r.random() < p

def rand_literal(r: random.Random):
    # Produce a mix of safe printable literals and escapes
    choice = r.random()
    if choice < 0.4:
        # plain literal chunk
        length = r.randint(1, 6)
        chars = []
        for _ in range(length):
            c = r.choice(ASCII + DIG + " _-.,:/@#+")
            chars.append(c)
        return "".join(chars)
    elif choice < 0.7:
        return rnd(r, SAFE_ESCAPES)
    else:
        # hex/octal/unicode escapes
        kind = r.randint(0, 3)
        if kind == 0:
            return "\\x" + r.choice(HEX) + r.choice(HEX)
        if kind == 1:
            # \x{...}
            n = r.randint(1, 6)
            return "\\x{" + "".join(r.choice(HEX) for _ in range(n)) + "}"
        if kind == 2:
            # \uXXXX style (PCRE2 supports \x{...}; \u is accepted in some modes). Use \x{XXXX}
            return "\\x{" + "".join(r.choice(HEX) for _ in range(4)) + "}"
        # octal up to 3 digits
        return "\\" + str(r.randint(0, 7)) + str(r.randint(0, 7)) + str(r.randint(0, 7))

def rand_class(r: random.Random):
    # Build a character class with ranges, posix, escapes, properties
    parts = []
    if maybe(r, 0.2):
        parts.append("^")
    k = r.randint(1, 4)
    for _ in range(k):
        t = r.random()
        if t < 0.35:
            a = r.choice(string.ascii_lowercase)
            b = r.choice(string.ascii_lowercase)
            if a > b:
                a, b = b, a
            parts.append(f"{a}-{b}")
        elif t < 0.55:
            parts.append(rnd(r, SAFE_ESCAPES))
        elif t < 0.75:
            parts.append("[:" + rnd(r, POSIX_CLASSES) + ":]")
        else:
            # property inside class via \p{..}
            parts.append("\\p{" + rnd(r, UNICODE_PROPS) + "}")
    return "[" + "".join(parts) + "]"

def rand_group(r: random.Random, depth: int):
    if depth <= 0:
        return rand_atom(r, depth)
    t = r.random()
    if t < 0.25:
        return "(" + rand_seq(r, depth - 1) + ")"
    elif t < 0.45:
        return "(?:" + rand_seq(r, depth - 1) + ")"
    elif t < 0.65:
        # named capture
        name = make_name(r)
        return "(?P<" + name + ">" + rand_seq(r, depth - 1) + ")"
    elif t < 0.8:
        # atomic group
        return "(?>" + rand_seq(r, depth - 1) + ")"
    else:
        # lookaround
        typ = r.randint(0, 3)
        if typ == 0:
            return "(?=" + rand_seq(r, depth - 1) + ")"
        if typ == 1:
            return "(?!" + rand_seq(r, depth - 1) + ")"
        if typ == 2:
            return "(?<=" + rand_seq(r, depth - 1) + ")"
        return "(?<!" + rand_seq(r, depth - 1) + ")"

def rand_atom(r: random.Random, depth: int):
    t = r.random()
    if t < 0.25:
        return rand_literal(r)
    if t < 0.45:
        return rand_class(r)
    if t < 0.55:
        # inline options
        opts_on = ''.join(sorted(set(r.sample(INLINE_OPT_SETS, r.randint(1, min(3, len(INLINE_OPT_SETS)))))))
