            return f"(?{opts_on})" + rand_atom(r, depth)
        else:
            # scoped options
            return f"(?{opts_on}:" + rand_seq(r, max(0, depth - 1)) + ")"
    if t < 0.65:
        # verb control
        v = rnd(r, VERBS)
        if v in ("SKIP", "THEN") and maybe(r, 0.6):
            return f"(*{v}:'{safe_word(r)}')"
        return f"(*{v})"
    if t < 0.75:
        # unicode property outside class
        return "\\p{" + rnd(r, UNICODE_PROPS) + "}"
    if t < 0.82:
        # anchors/boundaries
        return rnd(r, ["^", "$", r"\b", r"\B", r"\A", r"\z", r"\Z"])
    if t < 0.9:
        # subroutine/backref
        variant = r.randint(0, 3)
        if variant == 0:
            return r"\1"
        if variant == 1:
            return r"\g<1>"
        if variant == 2:
            nm = make_name(r)
            return f"(?P={nm})"  # named backref; may be unresolved but still valid syntax
        return "(?R)"
    # comment (extended mode aware); PCRE2 allows (?#...)
    cmt = ''.join(r.choice(ASCII + DIG + WS + "-_.,") for _ in range(r.randint(0, 8)))
    return f"(?#{cmt})"

