    if maybe(r, 0.6):
        q = rnd(r, QUANTIFIERS)
        return atom + q
    return atom

def rand_seq(r: random.Random, depth: int):
    n = r.randint(1, 4)
    parts = []
    for _ in range(n):
        if maybe(r, 0.45):
            g = rand_group(r, depth)
            parts.append(maybe_quantify(r, g))
        else:
            a = rand_atom(r, depth)
            parts.append(maybe_quantify(r, a))
    # occasional alternation
    if maybe(r, 0.5):
        arms = ["".join(parts)]
        for _ in range(r.randint(1, 2)):
            arms.append("".join(maybe_quantify(r, rand_atom(r, depth)) for __ in range(r.randint(1, 3))))
        return "|".join(arms)
    return "".join(parts)

