    # PCRE2 named group: start with letter/underscore, then letters/digits/underscore
    start = r.choice(string.ascii_letters + "_")
    rest = ''.join(r.choice(string.ascii_letters + string.digits + "_") for _ in range(r.randint(0, 6)))
    return start + rest

def add_callouts(r: random.Random, pattern: str):
    # Insert callouts at safe boundaries occasionally: (?C) or (?C<n>) and string callouts (?C'text')
    if len(pattern) < 2:
        return pattern
    pieces = []
    i = 0
    while i < len(pattern):
        pieces.append(pattern[i])
        if maybe(r, 0.08):
            kind = r.randint(0, 2)
            if kind == 0:
                pieces.append("(?C)")
            elif kind == 1:
                pieces.append(f"(?C{r.randint(0, 255)})")
            else:
                pieces.append(f"(?C'{safe_word(r)}')")
        i += 1
    return "".join(pieces)

def safe_word(r: random.Random):
    return ''.join(r.choice(string.ascii_letters + string.digits + " _-./:+") for _ in range(r.randint(1, 8)))

def ensure_valid_shape(pat: str):
    # Basic guardrails to avoid obviously invalid constructs:
    # - Balance brackets and parentheses roughly by appending closers if needed
    # - Avoid empty pattern; avoid exceeding 4096 bytes
    stack = []
    out = []
    i = 0
    while i < len(pat):
        ch = pat[i]
        out.append(ch)
        if ch == '(':
            # treat (?:, (?=, etc. as one opener
            stack.append(')')
        elif ch == '[':
            stack.append(']')
        elif ch == ')':
            if stack and stack[-1] == ')':
                stack.pop()
        elif ch == ']':
            if stack and stack[-1] == ']':
                stack.pop()
        i += 1
    # close any remaining
    while stack and len(out) < 4000:
        out.append(stack.pop())
    s = ''.join(out)
    if not s:
        s = "."
    # trim to <= 4096 bytes
    if len(s.encode('utf-8')) > 4096:
        # try to cut safely at a boundary
        s = s[:3000]
    return s

