    # Add anchors, inline options, or comments at start to exercise parser
    choices = []
    if maybe(r, 0.5):
        choices.append(rnd(r, ["^", r"\A", "\n?", ""]) )
    if maybe(r, 0.5):
        # inline option block that affects the whole pattern
        on = ''.join(sorted(set(r.sample(INLINE_OPT_SETS, r.randint(1, min(3, len(INLINE_OPT_SETS)))))))
        choices.append(f"(?{on})")
    if maybe(r, 0.3):
        choices.append("(?#pref)")
    return ''.join(choices)

def diversify_suffixes(r: random.Random) -> str:
    choices = []
    if maybe(r, 0.4):
        choices.append(rnd(r, ["$", r"\Z", r"\z", ""]))
    if maybe(r, 0.3):
        choices.append("(?#suf)")
    return ''.join(choices)

