    depth = r.randint(2, 4)
    core = rand_seq(r, depth)
    core = add_callouts(r, core)
    pat = diversify_prefixes(r) + core + diversify_suffixes(r)
    return ensure_valid_shape(pat)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # With some probability, choose themed patterns to trigger specific engines
    theme = r.random()
    if theme < 0.15:
        # Word boundary and backrefs with named groups
        name = make_name(r)
        pat = rf"\b(?P<{name}>[A-Za-z]{{2,}})\s+\1|(?P={name})"
    elif theme < 0.3:
        # Lookbehind/lookahead with alternatives and atomic groups
        pat = r"(?<=^|\s)(?>\p{L}+)\b(?=\s|$)"
    elif theme < 0.45:
        # Conditional on group and recursion/subroutine
        nm = make_name(r)
        pat = rf"(?P<{nm}>\w+)(?(?={{{nm}}})\g<{nm}>|,\s*\g<{nm}>)"
    elif theme < 0.6:
        # DFA-friendly alternations, classes, and quantifiers
        pat = r"(?:[[:alpha:]]{1,3}\d{0,2}|\h+|\R|\S{2,5})(?:,\s?(?-i:[A-Z]{2,4}))?"
    else:
        pat = build_pattern(r)

    pat = ensure_valid_shape(pat)
    # Final size guard
    b = pat.encode('utf-8', errors='strict')
    if len(b) > 4096:
        b = b[:4096]
    if not b:
        b = b"."
    return b

import random
import string
from typing import List

# Generator for PCRE2 pattern source text intended for pcre2_pattern_convert.
# The fuzzer stub passes explicit length (not ZERO_TERMINATED), so we can include NULs,
# but we keep inputs valid for common conversion modes (glob, POSIX basic/extended).
# We therefore emit patterns that are valid in those syntaxes and exercise features like:
# - Literals, character classes, ranges
# - Quantifiers *, +, ?, {m,n}
# - Grouping and alternation (for ERE)
# - Anchors ^, $
# - Escapes for glob (\*, \?, \[) and for POSIX (\., \+, \?, \{)
# - Glob-specific constructs: **, ?, *, [abc], [!abc]
# - Bracket expressions with collating elements/character classes ([:alpha:], [:digit:], etc.)
# - Path separators and dots to probe glob conversion edge cases
# - Mixed constructs to encourage different option bits to take effect
# The function must return bytes and be deterministic under a given seed, but still diverse.

_POSIX_CLASSES = [
    "alnum", "alpha", "blank", "cntrl", "digit", "graph", "lower",
    "print", "punct", "space", "upper", "xdigit"
]

_GLOB_LITERALS = list("abcdefghijklmno_pqrstuvwxyz-0123456789")
_GLOB_SEPARATORS = ["/", ".", "-"]

def _rand_rng(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)

def _choice(rng: random.Random, seq: List[str]) -> str:
    return seq[_rand_rng(rng, 0, len(seq)-1)]

def _weighted(rng: random.Random, items):
    # items: list of (value, weight)
    total = sum(w for _, w in items)
    x = rng.uniform(0, total)
    acc = 0.0
    for v, w in items:
        acc += w
        if x <= acc:
            return v
    return items[-1][0]

# Build POSIX BRE segment (basic regex)
# BRE treats (), {}, +, ? as literals unless escaped; \( \) for grouping, \{m,n\} for counts
# Use bracket classes and backrefs occasionally

def _posix_bre_segment(rng: random.Random) -> str:
    parts = []
    # Optional anchor
    if rng.random() < 0.3:
        parts.append("^")
    # Build a core with 2-6 tokens
    n = _rand_rng(rng, 2, 6)
    for _ in range(n):
        t = _weighted(rng, [
            ("lit", 4),
            ("dot", 2),
            ("class", 3),
            ("grp", 2),
            ("backref", 1),
            ("count", 2),
        ])
        if t == "lit":
            # Literal or escaped special
            ch = _choice(rng, list(string.ascii_letters + string.digits + " _-.:/"))
            if ch in ".*?+{}()|^$[]\\":
                parts.append("\\" + ch)
            else:
                parts.append(ch)
        elif t == "dot":
            parts.append(".")
        elif t == "class":
            kind = _weighted(rng, [("range", 3), ("posix", 2), ("neg", 1)])
            if kind == "posix":
                cls = _choice(rng, _POSIX_CLASSES)
                parts.append("[[:" + cls + ":]]")
            else:
                # build range list
                segs = []
                m = _rand_rng(rng, 1, 3)
                for _j in range(m):
                    a = _choice(rng, list(string.ascii_lowercase + string.digits))
                    b = _choice(rng, list(string.ascii_lowercase + string.digits))
                    if a <= b:
                        segs.append(a + "-" + b)
                    else:
                        segs.append(b + "-" + a)
                inner = "".join(segs)
                if kind == "neg":
                    parts.append("[^" + inner + "]")
                else:
                    parts.append("[" + inner + "]")
        elif t == "grp":
            # group must be escaped in BRE
            sub = _posix_bre_atom(rng)
            parts.append("\\(" + sub + "\\)")
        elif t == "backref":
            # backreference like \1..\9
            parts.append("\\" + str(_rand_rng(rng, 1, 3)))
        elif t == "count":
            atom = _posix_bre_atom(rng)
            m = _rand_rng(rng, 0, 3)
            n2 = _rand_rng(rng, m, m + 5)
            parts.append(atom + "\\{" + str(m) + "," + str(n2) + "\\}")
    if rng.random() < 0.3:
        parts.append("$")
    return "".join(parts)

def _posix_bre_atom(rng: random.Random) -> str:
    # A simple atom for counts/groups
    choice = _weighted(rng, [("lit", 3), ("dot", 1), ("class", 2)])
    if choice == "lit":
        ch = _choice(rng, list(string.ascii_letters + string.digits))
        if ch in ".*?+{}()|^$[]\\":
            return "\\" + ch
        return ch
    if choice == "dot":
        return "."
    # class
    cls = _choice(rng, _POSIX_CLASSES)
    return "[[:" + cls + ":]]"

# Build POSIX ERE segment (extended regex)
# ERE supports (), +, ?, | without escaping

def _posix_ere_segment(rng: random.Random) -> str:
    parts = []
    if rng.random() < 0.3:
        parts.append("^")
    # Compose with alternation
    k = _rand_rng(rng, 1, 3)
    alts = []
    for _i in range(k):
        seq = []
        n = _rand_rng(rng, 2, 5)
        for _ in range(n):
            seq.append(_posix_ere_atom(rng))
            # optional quantifier
            if rng.random() < 0.5:
                q = _weighted(rng, [("*", 3), ("+", 2), ("?", 2), ("{m,n}", 2), ("", 1)])
                if q == "{m,n}":
                    m = _rand_rng(rng, 0, 3)
                    n2 = _rand_rng(rng, m, m + 5)
                    seq[-1] += "{" + str(m) + "," + str(n2) + "}"
                else:
                    seq[-1] += q
        # optionally wrap in a group
        s = "".join(seq)
        if rng.random() < 0.4:
            s = "(" + s + ")"
        alts.append(s)
    parts.append("|".join(alts))
    if rng.random() < 0.3:
        parts.append("$")
    return "".join(parts)

def _posix_ere_atom(rng: random.Random) -> str:
    t = _weighted(rng, [("lit", 4), ("dot", 1), ("class", 3)])
    if t == "lit":
        ch = _choice(rng, list(string.ascii_letters + string.digits + " _-./:"))
        if ch in ".*?+{}()|^$[]\\":
            return "\\" + ch
        return ch
    if t == "dot":
        return "."
    # bracket expression with possible POSIX class or range
    if rng.random() < 0.4:
        cls = _choice(rng, _POSIX_CLASSES)
        return "[[:" + cls + ":]]"
    # build range list
    segs = []
    m = _rand_rng(rng, 1, 3)
    for _j in range(m):
        a = _choice(rng, list(string.ascii_lowercase + string.digits))
        b = _choice(rng, list(string.ascii_lowercase + string.digits))
        if a <= b:
            segs.append(a + "-" + b)
        else:
            segs.append(b + "-" + a)
    # occasionally negate
    inner = "".join(segs)
    if rng.random() < 0.3:
        return "[^" + inner + "]"
    return "[" + inner + "]"

# Build glob pattern segment
# Include ?, *, **/, [abc], [!abc], escapes for special chars, and path separators

def _glob_segment(rng: random.Random) -> str:
    parts = []
    # optional anchored at start for shells often implied by match start
    length = _rand_rng(rng, 3, 10)
    for i in range(length):
        t = _weighted(rng, [
            ("lit", 5),
            ("?", 2),
            ("*", 3),
            ("**/", 1.5),
            ("class", 2),
            ("sep", 2),
            ("esc", 1.5),
        ])
        if t == "lit":
            parts.append(_choice(rng, _GLOB_LITERALS))
        elif t == "?":
            parts.append("?")
        elif t == "*":
            # collapse multiple * sometimes
            if rng.random() < 0.4:
                parts.append("**")
            else:
                parts.append("*")
        elif t == "**/":
            parts.append("**/")
        elif t == "class":
            # [abc] or [!abc]
            neg = rng.random() < 0.3
            count = _rand_rng(rng, 2, 5)
            chars = ''.join(_choice(rng, list(string.ascii_lowercase + string.digits + "-_")) for _ in range(count))
            if neg:
                parts.append("[!" + chars + "]")
            else:
                parts.append("[" + chars + "]")
        elif t == "sep":
            parts.append(_choice(rng, _GLOB_SEPARATORS))
        elif t == "esc":
            ch = _choice(rng, ['*', '?', '[', ']', ' ', '.', '/', '-'])
            parts.append("\\" + ch)
    # Optionally ensure extension-like suffix
    if rng.random() < 0.4 and (not parts or parts[-1] != "/"):
        parts.append("." + _choice(rng, ["c", "h", "txt", "md", "json"]))
    return "".join(parts)

# Combine multiple syntaxes into one buffer to exercise options switching in converter.
# However, the converter expects one syntax specified by options. To keep validity high,
# we generate a pattern that is valid in multiple interpretations (e.g., glob-like path
# with bracket classes and literals) or choose one syntax per generation.

def _make_pattern(rng: random.Random) -> str:
    mode = _weighted(rng, [("glob", 4), ("ere", 3), ("bre", 3)])
    if mode == "glob":
        # Build multi-component glob with separators
        comps = [_glob_segment(rng) for _ in range(_rand_rng(rng, 1, 3))]
        pat = "/".join(c.strip('/') for c in comps)
        # sometimes anchor with leading ./ or **/
        if rng.random() < 0.3:
            pat = "./" + pat
        if rng.random() < 0.2:
            pat = "**/" + pat
        return pat
    if mode == "ere":
        return _posix_ere_segment(rng)
    return _posix_bre_segment(rng)

# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly choose number of patterns to concatenate with newline to explore multi-line handling
    # Many converters treat input as single pattern, but newlines are regular chars in POSIX/Glob.
    count = _rand_rng(rng, 1, 3)
    patterns = []
    for _ in range(count):
        p = _make_pattern(rng)
        patterns.append(p)
    data = "\n".join(patterns)
    # Ensure non-empty and within size limit
    if not data:
        data = "a"
    b = data.encode("utf-8", errors="strict")
    if len(b) > 4096:
        b = b[:4096]
    return b
